import{_ as t,a as o,b as a}from"./chunks/a017272816a0ef1329d6.BpGUEYVb.js";import{_ as s}from"./chunks/a7b3a30358c086b3a39e.CS8YSe9M.js";import{_ as n,C as l,o as i,c as m,j as e,a as h,E as g,a6 as c}from"./chunks/framework.CnPv4DE1.js";const N=JSON.parse('{"title":"工作更少，赚得更多（4小时工作日）","description":"","frontmatter":{"title":"工作更少，赚得更多（4小时工作日）","originalTitle":"Working Less Helps You Make More Money (The 4-Hour Workday)","date":"2023-06-10","originalUrl":"https://thedankoe.com/letters/working-less-helps-you-make-more-money-the-4-hour-workday/","minutes":12,"sourceHash":"10f70562b438925666cc97b6574ccda6dd2bf875f60c26b7fef26267f9c73abd","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/working-less-helps-you-make-more-money-the-4-hour-workday/"}]]},"headers":[],"relativePath":"letters/working-less-helps-you-make-more-money-the-4-hour-workday.md","filePath":"letters/working-less-helps-you-make-more-money-the-4-hour-workday.md"}'),u={name:"letters/working-less-helps-you-make-more-money-the-4-hour-workday.md"};function d(k,p,f,_,b,w){const r=l("ArticleMeta");return i(),m("div",null,[p[0]||(p[0]=e("h1",{id:"工作更少-赚得更多-4小时工作日",tabindex:"-1"},[h("工作更少，赚得更多（4小时工作日） "),e("a",{class:"header-anchor",href:"#工作更少-赚得更多-4小时工作日","aria-label":'Permalink to "工作更少，赚得更多（4小时工作日）"'},"​")],-1)),g(r),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/YW7yTzqedu8?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>当我告诉别人我每天工作不到4小时的时候，他们都不相信。</p><p>尤其是在我人生的这个阶段，我每天最多工作1-2个小时。</p><p>怎么做到的？</p><p><strong>1) 我一直专注于消除生活中我不喜欢的事情。</strong></p><p>我不喜欢冗长的客户电话或主持播客，所以我就不干了。</p><p>单单这两项，每周就帮我省下了好几个小时的时间。</p><p>当然，我不可能一蹴而就。</p><p>我必须<em>为我自己的问题创造一个解决方案。</em></p><p>客户工作完成了它的历史使命，直到我意识到个人品牌才是一条出路。因此，在一年的时间里，我每天早上都把它作为我的首要项目。</p><p>（顺便说一句，如果你没看出来的话，这主要是写给互联网创业者和创作者的。）</p><p><strong>2) 我一直专注于拥有最高杠杆的活动。</strong></p><p>自由职业和咨询工作是一个很好的起点，但需要投入大量时间。</p><p>如果你想要更多自由，你需要一个能在你睡觉时自动售卖、不需要你亲力亲为的产品。</p><p>随着时间的推移，我逐渐退出了客户服务工作，并利用我在品牌咨询方面取得的成果，创建了一个数字产品矩阵。</p><p>随着你的成长，时间金钱比必须降低。</p><p>接下来，我意识到写作是我理想的引流方式。</p><p>我每天早上都会写上1-2个小时。</p><p>是的，连周末也不例外。</p><p>不，我不想把这段时间花在任何其他事情上。</p><p>我的文章会被重新发布到每一个社交媒体平台上，从而让我的受众持续增长。</p><p>这就是大多数人失败的地方。</p><p>他们报了课程，课上清清楚楚地讲了哪些是高杠杆的任务，但他们转头就反着来。</p><p>当他们问：“Dan，为什么我没有拿到结果？”</p><p>我反问他们每天都在专注做些什么，结果几乎什么都没做。</p><p>他们并没有每天去执行那些能带来结果的行动。</p><p>他们拖延了3个小时，然后又花了8个小时去做无关紧要的事情。</p><p>结果需要时间来积累势能，而大多数人并没有耐心。</p><p><strong>3) 人们依然没有意识到读者增长的复利本质。</strong></p><p>商业，无论线上还是线下，都需要人和产品。</p><p>人流来源于广告、地理位置（对于实体商业而言）、像冷呼叫或邮件这样的手动拓展，或者在新型数字社会中通过内容创作来培养读者群。</p><p>大多数企业每天都要花上好几个小时试图去获取客户。</p><p>他们忽视了社交媒体的力量。</p><blockquote><p>我的创作者哲学：\\</p><ol><li><p>把盘子做大做宽，这样你就可以谈论任何你想谈的话题。\\</p></li><li><p>你的通讯、产品和服务会创造出从初级到高级的细分领域子受众群。\\</p></li></ol><p>这是一张在你自我实现的过程中，引导人们穿越需求层次的地图。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1667519489192128512?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">June 10, 2023</a></p></blockquote><p>我的意思是：</p><p>如果一个拥有5万粉丝的品牌每个月能赚5万美元（是的，<em>如果你懂行的话</em>，这只能算是垫底水平）……</p><p>如果我有50万粉丝，我只需要付出十分之一的努力就能赚到同样多的钱。</p><p>现在想象一下，如果我有200万粉丝（事实上我确实有），我每周只需工作一小时就能赚到那个数。</p><p>换句话说：</p><p>因为我过去几年投入的专注力，我可以赚到大多数人10倍的钱。而且我不屑于为了地位或迎合其他创业者而拉长工作时间。</p><p>我写一条推文，顶得上一个新手写10000条（无论是出于练习带来的高表现力想法，还是这条推文的传播广度）。</p><blockquote><p>我认识一个每天工作14小时的创业者\\</p><p>却只能憋屈地住在地下室里\\</p><p>我认识一个每天工作5小时的创业者\\</p><p>已经建立/出售了3家公司，每家售价都超过1亿美元\\</p><p>价值不在于你工作了多少个小时\\</p><p>而在于你把你的注意力/觉察力/意识聚焦在了哪里</p><p>— Tej Dosa (@ComedicBizman) <a href="https://twitter.com/ComedicBizman/status/1667192394536611841?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">June 9, 2023</a></p></blockquote><p>没有任何其他的引流方式具有这样的威力。</p><p>残酷的现实是，大多数人坚持得不够久。他们永远达不到能用一天时间换来一个月成果的那个境界。</p><p>大多数人并没有在提升自己的技能水平，他们只是在现有的技能水平上徒增时间消耗而已。</p><p>我在我的<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学大师班</a>中教授这种整体的商业模式，教你如何把自己变成一家企业。</p><p><strong>那么，<em>为什么</em>我每天只工作4个小时？</strong></p><p>似乎有越来越多的年轻创业者吹嘘自己总是在工作。</p><p>每天工作12-14个小时。</p><p>这没什么不对，我确信这也会很有趣。创业就是一场游戏，一场非常棒的游戏。</p><p>但是，这种生活方式存在一个明显的问题。</p><p>过度工作是全面发展的死敌，而整体性是实现向自我超越呈指数级增长的催化剂。</p><p>人们好奇为什么我每天只工作3-4小时（就平均而言，没有什么是绝对的）……</p><p>我反倒好奇，如果他们看重自我实现，为什么他们不这么做。</p><p>如果你如此痴迷于像金钱这种中性的事物，你怎么还会有时间去顾及创造力、人际关系和健康呢？</p><p>想象一下电子游戏里的天赋树。</p><p><img src="'+t+'" alt=""></p><p>如果你只关注一条路径，你就无法解锁更高等级的技能发展。</p><p>你能在商业上推进到一定的水平，但要想达到新的高度，你必须在健康、人际关系和认知发展上达到同等的水平。</p><p>回到我上面说过的“用一天时间换取一个月的成果”的观点，如果你<em>只</em>关注商业，这几乎是不可能的。</p><p>“专注于一件事”<em>要求</em>你同时关注许多其他事情，才能把那一件事做得更好。这很反直觉，就像生活中大多数美好的事物一样。</p><h2 id="朝九晚五工作的心理学-以及徒劳" tabindex="-1">朝九晚五工作的心理学（以及徒劳） <a class="header-anchor" href="#朝九晚五工作的心理学-以及徒劳" aria-label="Permalink to &quot;朝九晚五工作的心理学（以及徒劳）&quot;">​</a></h2><p>让我们通过严格区分工作和休息，来直面这个棘手的问题吧。</p><p>我们将<em>工作</em>归类为“生产力模式”，将<em>休息</em>归类为“创造力模式”。</p><p>两者都是一种心理状态，取决于你的注意力集中在什么上、是如何集中的，以及为什么集中。</p><p><img src="'+s+'" alt=""></p><p><strong>生产力模式</strong></p><p>这是一种狭隘集中的注意力状态。</p><p>你全神贯注于解决一项任务所带来的问题。</p><p>它几乎总是伴随着一种紧张感或表现压力。</p><p>在心理学中，这可以通过大脑中的<em>任务正向网络（Task Positive Network）</em>来完美诠释，它<em>“在需要集中注意力的任务中处于活跃状态，包括我们对<strong>外部</strong>环境的有意识关注。”</em></p><p><strong>创造力模式</strong></p><p>这是一种开放式的注意力状态。</p><p>你不会死盯着一项有压力的任务，但你依然可以保持专注。</p><p>你没有在主动地集中注意力。</p><p>这就是为什么你在洗澡、去健身房、散步或躺在阳光下时，会觉得自己如此有创造力。</p><p>在心理学中，这可以通过默认模式网络（Default Mode Network）来完美诠释，当我们的认知从向外转向<strong>向内</strong>聚焦时，它就会被激活。</p><p><strong>问题所在</strong></p><p>过度工作者没有意识到，习惯不仅关乎你做什么，更关乎你是谁。</p><p>一种心理状态，比如生产力模式，会被植入你的大脑变成条件反射。</p><p>你可能一直生活在那狭隘和充满压力的视角中，这在无形中摧残着你的健康。</p><p>问题的关键就在这里……</p><p>你根本不在乎。</p><p>为什么？</p><p>因为这就是你所知道的一切。</p><p>你变得更加自负和自私，仅仅是因为你无法想象一种更好的生活方式。</p><p>你目前的觉察力/意识水平不允许你够到更高的阶梯，因为它被迷雾遮蔽了。</p><p>你的生活是如此机械和“已知”，以至于你从未想过存在一种可以使你受益的未知。</p><p>一想到你可以每天只工作3-4小时却取得更大的进步，你的自我认同就会受到威胁。而且你害怕自己会被抛入那种未知的生活方式中。</p><p>于是，自我（ego）死死地攥住了你的生活方式，让你继续做你一直在做的事情。</p><p><strong>进化</strong></p><p>我并不是说生产力模式不好。</p><p>事实上，这是最令人享受的心理状态之一。</p><p>踏实、确定且专注，所以负面情绪不会在你的大脑中滋生。</p><p>这不是问题所在。</p><p>问题在于，你从来没有打破那种状态去反思过去，重新瞄准未来。</p><p>你从不<em>拉远视角</em>看看你要去哪里，因此你也就无法<em>拉近视角</em>去做出更好的选择。</p><p>大多数人一辈子都在拉近视角。某天醒来，他们只会纳闷自己到底哪一步走错了。</p><p>拉远视角。</p><p>找出一个宏大的目标，以此获得愿景。</p><p>透过这个目标的镜头去审视你的日常选择。</p><p>大多数努力工作的创业者都会嗤之以鼻，认为他们和朝九晚五的上班族完全一样，但事实就是如此。</p><p>解释这一点的最好方式是<em>技能与挑战的匹配：</em></p><p><img src="'+o+'" alt=""></p><p>挑战是获得最大乐趣（心流状态）的关键。</p><p>我在<a href="/letters/life-is-a-game-heres-how-you-play-it">生活是一场电子游戏</a>中谈到过这一点。</p><p>挑战将大脑的注意力缩窄在阻挡通往意义目标道路上的问题上，而这就是进化的驱动力。</p><p>我们都能感觉到那种向“最高版本”拉扯的“牵引力”。</p><p>这是进化在召唤你遵循自然法则生活。</p><p>人们没有意识到，这是一种不断进化的生活方式。</p><p>停滞 = 死亡。</p><p>为了达到能让你集中注意力的新级别挑战，你必须：</p><ul><li>永不停止学习，去叠加新的技能和视角</li><li>增加你性格的复杂性，以至于能察觉到这些挑战</li><li>解决生活中更深层次的问题，这样你才不会被困在表象之中</li></ul><p>这就是我对大多数朝九晚五工作的不满。</p><p>是的，有些工作能让你进步，但那是一种缓慢的煎熬，并且不可避免地存在天花板。</p><p>我把朝九晚五的工作视为垫脚石。</p><p>它们滋生自满情绪，对你的心灵有害。</p><p>挑战使生活变得充满乐趣和趣味。</p><p>如果你不再追求更多从而停止了个人进化，你就会失去目标和成就感。</p><p>当然，现在人们都有自己的目标。</p><p>人们可以通过终身的朝九晚五工作和正念方法来实现持续的幸福感。</p><p>但我不是在对那些人说话。</p><p>我是在对你说话。</p><p>一个显然渴望更多的人。</p><p>一个带着发现自身潜力天生好奇心的人。</p><p>否则，你就不会在读这篇文章了。</p><h2 id="创造力与杠杆" tabindex="-1">创造力与杠杆 <a class="header-anchor" href="#创造力与杠杆" aria-label="Permalink to &quot;创造力与杠杆&quot;">​</a></h2><blockquote><p>如果一项工作不需要创造力，要么委派给别人，要么自动化，要么干脆别做。</p><p>— Naval (@naval) <a href="https://twitter.com/naval/status/1311199771676176384?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">September 30, 2020</a></p></blockquote><p>创造力是生产力的平衡点。</p><p>持续的生产力需求会导致持续的压力。</p><p>持续的压力会导致肤浅的生活。你甚至意识不到生活还有更深的维度。除了与工作相关的任务，你很难敞开你的心扉。</p><p>这会影响你生活的其他方方面面。</p><ul><li>与朋友和爱人的关系。</li><li>从与健康相关的活动中恢复的能力。</li><li>你的心智能力与发展（这决定了你未来真正的财富水平）。</li></ul><p>每天工作4小时、单一的专注以及有意义的工作，正在互联网的一小部分群体中成为常态，这是有充分理由的。</p><p>古罗马人和古希腊人、史蒂夫·乔布斯（Steve Jobs）、查尔斯·达尔文（Charles Darwin），以及越来越多有远见的人、战略家和创新者，都将他们的成功归功于令人惊讶的极短工作时间，以及伴随而来的大量如长时间散步等休闲活动。</p><p>当我们看到某人拥有令人心生敬意的海量创意作品时，我们会以为他们工作时间很长，为了下一部作品的细节痴迷地熬到深夜。</p><p>然而，事实恰恰相反。</p><p>比如达尔文，在晨间散步和吃过早餐后，八点来到他的书房。</p><p>他会工作一个半小时，然后休息一下，读读邮件、写写信，接着再回到更严肃的工作中去进行他的实验。</p><p>到了中午，达尔文就会结束一天的工作，出门进行长时间的散步。</p><p>在阅读并回复了几封信件之后，他会睡个午觉，再散一次步，然后回到书房进行另一个时段的工作。</p><p>3-5小时的工作加上积极的休息，似乎是大多数具有影响力的创作者的最佳平衡点。</p><p>来自不同领域的海明威（Hemingway）、塔伦蒂诺（Tarantino）和奥格威（Ogilvy）等作家，会把一天中的大部分时间花在泳池边闲聊、与美女交谈，以及做任何在他们看来不属于工作的事情上。</p><p>他们为创意的涌现留出了空间，而正是这些想法为他们作品的影响力注入了燃料。</p><p>如果他们能用这种方法改变文化和商业，为什么职场上的工作狂就不能做同样的事呢？</p><p>如果你想知道“如何”做到这一点，我之前已经详细写过了。</p><p>这是我的<a href="/letters/the-4-hour-workday-focused-work-changed-my-life">4小时工作制的10条戒律</a>以及<a href="/letters/change-your-life-in-6-months-my-deep-work-routine">我的深度工作日常</a>。</p><h2 id="新货币" tabindex="-1">新货币 <a class="header-anchor" href="#新货币" aria-label="Permalink to &quot;新货币&quot;">​</a></h2><p>你该如何赚钱？</p><p>首先，你需要注意力。</p><p>其次，你需要一个产品或服务，将这些注意力引导过去。</p><p>第三，你需要理解在整个旅程中<em>引导注意力</em>的过程。</p><p>有些人可能会偶然看到你的产品并随机购买。</p><p>在大多数情况下，这是不可持续的。</p><p>你必须创造并理解用户在你的品牌上可能接触到的每一个触点。</p><p>有些人称之为“漏斗”，但这个词带有与黑心营销客相关的负面含义。</p><p>我的漏斗很简单：</p><ul><li>每周写一篇以大想法为中心的新闻通讯。</li><li>每天写3条有冲击力且令人难忘的推文。</li><li>将它们重新发布到所有平台（我的新闻通讯也是我的YouTube视频脚本，<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">我在这里教你我是如何写出它们的</a>）。</li></ul><p><img src="'+a+'" alt=""></p><p>你必须用<em>想法</em>来捕捉、保持并培育他们的注意力。</p><p><em>想法就是新货币。</em></p><p><em>现代的成功是一场心理战。</em></p><p><em>创造力、休息以及较短的工作时间是催化剂。</em></p><p>这是我在旅途中很晚才意识到的事情。</p><p>以下是你需要关注的重点：</p><p><strong>如果你不</strong> <strong>优先考虑</strong> <strong>深度，你就不会</strong> <strong>被记住****。</strong></p><p>你的权威取决于你在这一生中能占据多少注意力。</p><p>一条推文或许能占据10秒的注意力。</p><p>一本书能占据5-6小时的注意力。</p><p>你摄入什么，就会成为什么；同样，你也在塑造那些阅读你作品的人。</p><p>书籍、新闻通讯、播客和YouTube视频。</p><p>这些是你品牌的基石。</p><p>这就是你培育受众的方式，完全不需要咄咄逼人的推销手段和直接响应营销。</p><p>当你优先考虑深度、理解和新颖的视角时，你就是在与受众建立信任和品牌资产，等到需要推广时，你就可以将它们变现。</p><p>你会记住谁？</p><p>是那个在Twitter上发了你点赞的推文的人？</p><p>还是那个改变了你在这个世界行事方式的作者？</p><p>我不记得我读过的埃克哈特·托利（Eckhart Tolle）的所有内容，但我会把他的作品传播给任何好奇是谁对我生活影响最大的人。</p><p>他从我这里赚到了钱，因为他在我脑子里免租常住。</p><h3 id="全面生活方式的-填补-清空-使用-框架" tabindex="-1">全面生活方式的“填补-清空-使用”框架 <a class="header-anchor" href="#全面生活方式的-填补-清空-使用-框架" aria-label="Permalink to &quot;全面生活方式的“填补-清空-使用”框架&quot;">​</a></h3><blockquote><p>下午通过看书、学习和社交来填补你的大脑\\</p><p>睡前通过写日记、计划和冥想来清空你的大脑\\</p><p>早上通过创造、输出和专注来使用你的大脑</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1456553636700504065?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">November 5, 2021</a></p></blockquote><p>在下午，通过以下方式填补你的头脑：</p><p><strong>追随好奇心</strong>，收集真理的颗粒，将它们整合到你的世界观中。</p><p><strong>获取技能</strong>，在不断变化的市场中提升你的价值。如果你停止学习，你就死定了。</p><p><strong>智性对话</strong>，这样你就不会受困于狭隘的视角。你需要以开放的心态来检验你的想法。避免辩论和争吵。</p><p>所有这些都可以作为你创意工作的燃料。</p><p>在下午，通过以下方式清空你的头脑：</p><p><strong>自我反思</strong>，记录下否则你就会错过的错误、教训和方向。</p><p><strong>现实映射</strong>（或记录你今天学到了什么，以及它是如何与其他想法相联系的），这样你就能创造出有价值的东西。</p><p><strong>精神连接</strong>，这样你就不会受困于“做事”模式。拥抱“存在”的状态，以平衡压力。</p><p>在早上，通过以下方式使用你的头脑：</p><p><strong>专注工作</strong>，引导你的发现并精进你的技艺。</p><p><strong>优先项目</strong>，让你的工作有方向。这是产出能传递给他人（并因此获得报酬）的东西的唯一途径。</p><p>关于优先项目的更多信息在这里：<a href="/letters/change-your-life-in-6-months-my-deep-work-routine">在6个月内改变你的生活（我的深度工作日常</a>).</p><p><strong>爆发性的高强度</strong>，这样你一早就能感受到成就感。在休息时你可以安心，因为你知道自己已经搞定了需要做的事情。</p><p>今天就写到这里。</p><p>享受这周余下的时光。</p><p>– Dan Koe</p><hr><p><a href="/en/letters/working-less-helps-you-make-more-money-the-4-hour-workday">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',200))])}const v=n(u,[["render",d]]);export{N as __pageData,v as default};
